 1→import { useEffect, useMemo, useRef } from "react";
 2→
 3→interface DebouncedFunction<A extends unknown[]> {
 4→  (...args: A): void;
 5→  cancel: () => void;
 6→}
 7→
 8→/**
 9→ * `useDebouncedCallback` returns a debounced version of the provided callback
10→ * that automatically cancels pending invocations on unmount.
11→ * @param callback - the function to debounce
12→ * @param delay - debounce delay in milliseconds
13→ * @returns a debounced function with a `.cancel()` method
14→ */
15→export const useDebouncedCallback = <A extends unknown[]>(
16→  callback: (...args: A) => void,
17→  delay: number,
18→): DebouncedFunction<A> => {
19→  // When upgraded to React 19, this could be a useEffectEvent
20→  const callbackRef = useRef(callback);
21→  useEffect(() => {
22→    callbackRef.current = callback;
23→  });
24→
25→  const timeoutRef = useRef<ReturnType<typeof setTimeout>>();
26→
27→  const debouncedFn = useMemo(() => {
28→    const fn = ((...args: A) => {
29→      clearTimeout(timeoutRef.current);
30→      timeoutRef.current = setTimeout(() => {
31→        callbackRef.current(...args);
32→      }, delay);
33→    }) as DebouncedFunction<A>;
34→
35→    fn.cancel = () => {
36→      clearTimeout(timeoutRef.current);
37→    };
38→
39→    return fn;
40→  }, [delay]);
41→
42→  useEffect(() => () => debouncedFn.cancel(), [debouncedFn]);
43→
44→  return debouncedFn;
45→};
