  render: () => {
    const [state, setState] = useState<string[]>(['all']);
    return (
      <TreeSelect
        tData={sampleData}
        state={state}
        onChange={setState}
      />
    );
  },
  play: async ({ canvas }) => {
    await expect(canvas.getByText('All')).toBeVisible();
  },
};

