 1→import { DependencyList, EffectCallback, useEffect, useState } from "react";
 2→
 3→/**
 4→ * `usePrevious` is a custom hook that returns the previous value of a given value
 5→ * @param value - the value to track
 6→ * @param initialValue - the initial value
 7→ * @returns the previous value
 8→ */
 9→const usePrevious = <T>(value: T, initialValue: T) => {
10→  const [previous, setPrevious] = useState(initialValue);
11→
12→  useEffect(() => {
13→    setPrevious(value);
14→  }, [value]);
15→
16→  return previous;
17→};
18→
19→/**
20→ * `useEffectDebugger` is a custom hook that logs the changed dependencies of a useEffect hook
21→ * @param effectHook - the effect hook
22→ * @param dependencies - an array of dependencies
23→ * @param dependencyNames - an array of strings that correspond to the dependencies
24→ */
25→const useEffectDebugger = (
26→  effectHook: EffectCallback,
27→  dependencies: DependencyList,
28→  dependencyNames: string[] = [],
29→) => {
30→  if (process.env.NODE_ENV !== "development") {
31→    console.warn(
32→      "[use-effect-debugger] This hook should only be used in development!",
33→    );
34→  }
35→  if (dependencies.length !== dependencyNames.length) {
36→    console.warn(
37→      "[use-effect-debugger] The number of dependencies and dependency names should be the same!",
38→    );
39→  }
40→  const previousDeps = usePrevious(dependencies, []);
41→
42→  const changedDeps = dependencies.reduce(
43→    (
44→      accum: Record<string, { before: unknown; after: unknown }>,
45→      dependency,
46→      index,
47→    ) => {
48→      if (dependency !== previousDeps[index]) {
49→        const keyName = dependencyNames[index] || index;
50→        return {
51→          ...accum,
52→          [keyName]: {
53→            before: previousDeps[index],
54→            after: dependency,
55→          },
56→        };
57→      }
58→
59→      return accum;
60→    },
61→    {} as Record<string, { before: unknown; after: unknown }>,
62→  );
63→
64→  if (Object.keys(changedDeps).length) {
65→    console.log("[use-effect-debugger] ");
66→    console.table(changedDeps);
67→  }
68→
69→  // eslint-disable-next-line react-hooks/exhaustive-deps
70→  useEffect(effectHook, dependencies);
71→};
72→
73→export { useEffectDebugger };
