// Stub for @emotion/server/create-instance in browser environment
// @leafygreen-ui/emotion calls createEmotionServer(cache) which returns
// { extractCritical, renderStylesToString, renderStylesToNodeStream }
const createEmotionServer = () => ({
  extractCritical: (html: string) => ({ html, css: '', ids: [] as string[] }),
  extractCriticalToChunks: (html: string) => ({ html, styles: [] as unknown[] }),
  renderStylesToString: (html: string) => html,
  renderStylesToNodeStream: () => null,
});

export default createEmotionServer;
export const extractCritical = createEmotionServer().extractCritical;
export const renderStylesToString = createEmotionServer().renderStylesToString;
export const renderStylesToNodeStream = createEmotionServer().renderStylesToNodeStream;

// Stub for @emotion/server/create-instance in browser environment
function createEmotionServer() {
  return {
    extractCritical: function(html) { return { html: html, css: '', ids: [] }; },
    extractCriticalToChunks: function(html) { return { html: html, styles: [] }; },
    renderStylesToString: function(html) { return html; },
    renderStylesToNodeStream: function() { return null; },
  };
}

module.exports = createEmotionServer;
module.exports.default = createEmotionServer;

